
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE phone_numbers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    -- HMAC-SHA-256 of the canonical E.164 number.
    -- Generated by the trusted backend, not the client.
    lookup_hash BYTEA UNIQUE NOT NULL,

    -- Encrypted E.164 value; encryption is performed
    -- by the backend using a managed key.
    encrypted_number BYTEA,

    country_code CHAR(2) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CHECK (country_code ~ '^[A-Z]{2}$')
);

CREATE TABLE fraud_reports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    phone_id UUID NOT NULL
        REFERENCES phone_numbers(id),

    reporter_id UUID,
    incident_type TEXT NOT NULL CHECK (
        incident_type IN (
            'impersonation',
            'payment_scam',
            'phishing',
            'advance_fee',
            'harassment',
            'other'
        )
    ),

    description TEXT,
    incident_at TIMESTAMPTZ,
    submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    status TEXT NOT NULL DEFAULT 'pending' CHECK (
        status IN (
            'pending',
            'under_review',
            'substantiated',
            'unsubstantiated',
            'rejected',
            'withdrawn'
        )
    ),

    -- Prevent clients from publishing reports as verified.
    reviewed_at TIMESTAMPTZ
);

CREATE TABLE evidence_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    source_type TEXT NOT NULL CHECK (
        source_type IN (
            'user_attachment',
            'public_web',
            'trusted_partner',
            'official_alert'
        )
    ),

    source_name TEXT,
    source_url TEXT,
    source_reference TEXT,
    content_hash BYTEA,
    observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    retrieved_at TIMESTAMPTZ,
    quality_status TEXT NOT NULL DEFAULT 'unreviewed'
        CHECK (quality_status IN (
            'unreviewed',
            'credible',
            'disputed',
            'invalid'
        ))
);

CREATE TABLE report_evidence (
    report_id UUID NOT NULL
        REFERENCES fraud_reports(id) ON DELETE CASCADE,
    evidence_id UUID NOT NULL
        REFERENCES evidence_items(id),
    relation TEXT NOT NULL DEFAULT 'supports'
        CHECK (relation IN (
            'supports',
            'contradicts',
            'context'
        )),
    PRIMARY KEY (report_id, evidence_id, relation)
);

CREATE TABLE moderation_reviews (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    report_id UUID NOT NULL
        REFERENCES fraud_reports(id),
    reviewer_id UUID NOT NULL,
    decision TEXT NOT NULL CHECK (
        decision IN (
            'substantiated',
            'unsubstantiated',
            'rejected',
            'needs_more_evidence'
        )
    ),
    reason_code TEXT NOT NULL,
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE risk_assessments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    phone_id UUID NOT NULL
        REFERENCES phone_numbers(id),

    score SMALLINT NOT NULL
        CHECK (score BETWEEN 0 AND 100),
    risk_level TEXT NOT NULL CHECK (
        risk_level IN (
            'high',
            'suspicious',
            'no_known_reports',
            'insufficient_information'
        )
    ),

    evidence_count INTEGER NOT NULL DEFAULT 0,
    verified_report_count INTEGER NOT NULL DEFAULT 0,
    scoring_version TEXT NOT NULL,
    explanation JSONB NOT NULL DEFAULT '{}',

    assessed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ
);

CREATE INDEX reports_phone_status_idx
    ON fraud_reports (phone_id, status, submitted_at DESC);

CREATE INDEX assessments_phone_date_idx
    ON risk_assessments (phone_id, assessed_at DESC);

CREATE INDEX evidence_quality_idx
    ON evidence_items (quality_status, observed_at DESC);

CREATE TABLE trusted_sources (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    source_type TEXT NOT NULL,
    approved BOOLEAN NOT NULL DEFAULT FALSE,
    last_checked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE audit_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    actor_id UUID,
    action TEXT NOT NULL,
    resource_type TEXT NOT NULL,
    resource_id UUID,
    metadata JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

